export type TranslationTables = Readonly<Record<string, Readonly<Record<string, string>>>>;

export class PhraseBook {
  private readonly tables: Record<string, Record<string, string>>;

  public constructor(
    private readonly defaultLocale: string,
    tables: TranslationTables,
  ) {
    if (tables[defaultLocale] === undefined) {
      throw new RangeError("Missing default locale");
    }
    this.tables = Object.fromEntries(
      Object.entries(tables).map(([locale, values]) => [locale, { ...values }]),
    );
  }

  public lookup(key: string, locale: string): string {
    const requested = this.tables[locale];
    if (requested !== undefined && Object.prototype.hasOwnProperty.call(requested, key)) {
      return requested[key];
    }
    return `[${key}]`;
  }
}
```

