import { PhraseBook } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

const tables: Record<string, Record<string, string>> = {
  en: { hello: "Hello", shared: "English", empty: "" },
  fr: { hello: "Bonjour", empty: "" },
};
const book = new PhraseBook("en", tables);
assert(book.lookup("hello", "fr") === "Bonjour", "requested locale wins");
assert(book.lookup("shared", "fr") === "English", "missing requested key falls back to default locale");
assert(book.lookup("shared", "unknown") === "English", "unsupported locale falls back to default locale");
assert(book.lookup("absent", "fr") === "[absent]", "placeholder after both lookups miss");
assert(book.lookup("empty", "fr") === "", "empty requested translation is valid");
assert(book.lookup("empty", "unknown") === "", "empty default translation is valid");

tables.fr.hello = "Changed";
tables.en.shared = "Changed default";
tables.en.added = "Added later";
delete tables.en.hello;
assert(book.lookup("hello", "fr") === "Bonjour", "requested table defensively copied");
assert(book.lookup("shared", "fr") === "English", "default table defensively copied");
assert(book.lookup("added", "fr") === "[added]", "later keys are not retained by alias");
assert(book.lookup("hello", "unknown") === "Hello", "later deletion does not affect lookup");

let threw = false;
try {
  new PhraseBook("de", { en: { hello: "Hello" } });
} catch (error: unknown) {
  threw = error instanceof RangeError && error.message === "Missing default locale";
}
assert(threw, "missing default locale must throw specified RangeError");

